    import time

    LANGUAGE_WRAPPER = 'Consider a cyclic sequence of {alpha} real numbers a_1, a_2, ..., a_{alpha}. Fix a step size {step} with 1 <= {step} < {alpha}, and interpret indices modulo {alpha}. Define the set of pair-sums S_{step} = { |a_i + a_{i+{step}}| : i = 1, 2, ..., {alpha} }. Determine the smallest positive integer t such that for every choice of the reals a_1, ..., a_{alpha}, the inequality max_{1 <= i <= {alpha}} |a_i| <= t * max S_{step} always holds.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate alpha and step such that m = alpha/gcd(alpha, step) is odd and >= 5,
# ensuring a nontrivial and valid inequality. We also keep alpha reasonably large.
def _gcd(a, b):
    while b:
        a, b = b, a % b
    return a
for _ in range(1000):
    # Choose a large odd alpha
    alpha = rng.randrange(1001, 20001, 2)  # odd in [1001, 20000]
    # Choose step uniformly from 1..alpha-1
    step = rng.randint(1, alpha - 1)
    g = _gcd(alpha, step)
    m = alpha // g
    if m % 2 == 1 and m >= 5:
        return {"alpha": alpha, "step": step}
# Fallback deterministic construction if random attempts fail (very unlikely)
# Pick an odd alpha and step=1 ensures m=alpha odd
alpha = 20001  # odd
step = 1
return {"alpha": alpha, "step": step}

